import itertools,numpy as np

def rank2(cols):
 basis={}
 for c in cols:
  while c:
   k=c.bit_length()-1
   if k in basis:c^=basis[k]
   else:basis[k]=c;break
 return len(basis)
for n in range(2,8):
 for d in range(0,n):
  N=2*n
  adj=[set() for _ in range(N)]
  for i in range(n):
   adj[i]=set(range(n))-{i}|{n+i};adj[n+i]={i}
  faces=[[] for _ in range(N+1)]
  for mask in range(1<<N):
   S=[i for i in range(N) if mask>>i&1]
   if all(sum(j in adj[i] for j in S)<=d for i in S):faces[len(S)].append(mask)
  rs=[0]*(N+2)
  for k in range(1,N+1):
   lookup={x:i for i,x in enumerate(faces[k-1])}
   cs=[]
   for x in faces[k]:
    cs.append(sum(1<<lookup[x^(1<<i)] for i in range(N) if x>>i&1))
   rs[k]=rank2(cs)
  hs=[(k-1,len(faces[k])-rs[k]-rs[k+1]) for k in range(1,N+1) if len(faces[k])-rs[k]-rs[k+1]]
  print(n,d,hs)

